  const [offerStatus, setOfferStatus] = useState<"Published" | "Closed">("Published");
  const [applicationStatus, setApplicationStatus] = useState<"Not submitted" | "Pending" | "Suspended">("Not submitted");
  const [pickupDate, setPickupDate] = useState("2026-10-22");
  const [cutoffTime, setCutoffTime] = useState("18:00");

  const visibleMeals = useMemo(() => {
    if (scenario === "No matches" || scenario === "Loading") return [];
    return meals.filter((meal) => !(meal.id === "soup" && (offerStatus === "Closed" || applicationStatus === "Suspended")) && (!query || meal.title.toLowerCase().includes(query.toLowerCase()) || meal.cook.toLowerCase().includes(query.toLowerCase())) && (cuisine === "Any cuisine" || meal.cuisine === cuisine) && (!tag || meal.tags.includes(tag)));
  }, [query, cuisine, tag, scenario, offerStatus, applicationStatus]);

