  const notice = (children: ReactNode, tone: "gold" | "red" | "green" = "gold") => <div className={`nk-notice ${tone}`}>{children}</div>;
  const publishingBlocked = applicationStatus === "Pending" || applicationStatus === "Suspended" || scenario === "Suspended cook";
  const contactBlocked = scenario === "Expired link" || scenario === "Closed offer" || scenario === "Suspended cook" || offerStatus === "Closed" || applicationStatus === "Suspended";
  const contactAuthorized = demoSignedIn && !contactBlocked;

